import React from "react";
import { Form } from "antd";

// eslint-disable-next-line react/prop-types
export default function CustomForm({
  layout,
  handleFinish,
  children,
  className,
}) {
  return (
    <Form layout={layout} onFinish={handleFinish} className={className}>
      {children}
    </Form>
  );
}
